#include <bits/stdc++.h>
using namespace std;
struct R {int mask,sum;array<array<unsigned long long,32>,6> p{};};
int main(int argc,char**argv){int k=argc>1?atoi(argv[1]):9, trials=argc>2?atoi(argv[2]):1000;vector<int>id,lab;int s,a,b;while(cin>>s>>a>>b){id.push_back(s);lab.push_back((a<<7)|b);}int N=id.size();mt19937 rng(460019+k);vector<int>order(N);iota(order.begin(),order.end(),0);long long candidates=0;for(int trial=0;trial<trials;trial++){shuffle(order.begin(),order.end(),rng);vector<vector<R>> sides(2);for(int side=0;side<2;side++){int n=14,m=1<<n;vector<int>su(m),sz(m);for(int mask=1;mask<m;mask++){int j=__builtin_ctz(mask),prev=mask&(mask-1),v=lab[order[side*14+j]];su[mask]=((su[prev]^v)&1920)|((su[prev]+v)&127);sz[mask]=sz[prev]+1;}for(int mask=0;mask<m;mask++)if(sz[mask]==k){R r;r.mask=mask;r.sum=su[mask];for(int t=mask;t;t=(t-1)&mask){int c=sz[t];if(c>=2&&c<=k/2)r.p[c][su[t]>>6]|=1ULL<<(su[t]&63);}sides[side].push_back(r);}}array<vector<int>,2048>bins;for(int i=0;i<(int)sides[0].size();i++)bins[sides[0][i].sum].push_back(i);for(auto&b:sides[1])for(int i:bins[b.sum]){candidates++;auto&a=sides[0][i];bool primitive=true;for(int c=2;c<=k/2&&primitive;c++)for(int j=0;j<32;j++)if(a.p[c][j]&b.p[c][j]){primitive=false;break;}if(primitive){cout<<"{\"slots\":"<<2*k<<",\"trial\":"<<trial<<",\"candidates\":"<<candidates<<",\"plus\":[";bool first=true;for(int j=0;j<14;j++)if(a.mask>>j&1){if(!first)cout<<",";cout<<id[order[j]];first=false;}cout<<"],\"minus\":[";first=true;for(int j=0;j<14;j++)if(b.mask>>j&1){if(!first)cout<<",";cout<<id[order[14+j]];first=false;}cout<<"]}"<<endl;return 0;}}if(trial%100==0)cerr<<"trial "<<trial<<" candidates "<<candidates<<endl;}cerr<<"NONE "<<candidates<<endl;return 1;}
